const incoming = $input.first().json;
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const companyName = String(body.companyName ?? body.company ?? body.name ?? '').trim();
const requestedAmount = Number(body.requestedAmount ?? body.loanAmount ?? 0);
if (!companyName) throw new Error('companyName is required.');
if (!Number.isFinite(requestedAmount) || requestedAmount <= 0) throw new Error('requestedAmount must be a positive number.');
return [{json:{
  companyName,
  requestedAmount,
  currency: String(body.currency || 'INR').toUpperCase(),
  applicantId: String(body.applicantId || `CL-${Date.now()}`),
  receivedAt: new Date().toISOString()
}}];

const req = $('Validate Application').first().json;
const raw = $input.first().json || {};
const quotes = Array.isArray(raw.quotes) ? raw.quotes : [];
const news = Array.isArray(raw.news) ? raw.news : [];

function norm(s){
  return String(s||'').toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]/g,'');
}
const input=String(req.companyName||'').trim();
const target=norm(input);

// Deterministic aliases prevent Yahoo's fuzzy search from mapping short names such as
// "Infosys" to similarly named but unrelated listings such as HCL Infosystems.
const aliases={
  'infosys':'INFY.NS',
  'infosyslimited':'INFY.NS',
  'tcs':'TCS.NS',
  'tataconsultancyservices':'TCS.NS',
  'tatamotors':'TMPV.NS',
  'tatamotorslimited':'TMPV.NS',
  'reliance':'RELIANCE.NS',
  'relianceindustries':'RELIANCE.NS',
  'relianceindustrieslimited':'RELIANCE.NS',
  'itc':'ITC.NS',
  'itclimited':'ITC.NS',
  'sunpharma':'SUNPHARMA.NS',
  'sunpharmaceutical':'SUNPHARMA.NS',
  'sunpharmaceuticalindustries':'SUNPHARMA.NS',
  'adani':'ADANIENT.NS',
  'adanienterprises':'ADANIENT.NS',
  'zomato':'ZOMATO.NS',
  'eternal':'ETERNAL.NS',
  'jswsteel':'JSWSTEEL.NS',
  'hcltech':'HCLTECH.NS',
  'wipro':'WIPRO.NS',
  'hdfcbank':'HDFCBANK.NS',
  'icicibank':'ICICIBANK.NS',
  'bhartiairtel':'BHARTIARTL.NS'
};

let forcedSymbol=aliases[target]||null;
if(!forcedSymbol && /^[A-Z0-9.-]+\.(NS|BO)$/i.test(input)) forcedSymbol=input.toUpperCase();

let m=null;
if(forcedSymbol){
  const exact=quotes.find(q=>String(q.symbol||'').toUpperCase()===forcedSymbol);
  m=exact||{symbol:forcedSymbol,shortname:input,longname:input,exchange:forcedSymbol.endsWith('.BO')?'BSE':'NSI',quoteType:'EQUITY',currency:req.currency};
}

if(!m){
  const scored=quotes.filter(q=>q?.symbol).map((q,i)=>{
    const names=[q.symbol,q.shortname,q.longname,q.displayName].filter(Boolean).map(norm);
    const words=norm(input).split(/(?=[A-Z])/);
    let score=0;
    if(names.some(x=>x===target)) score+=1000;
    if(names.some(x=>x===target+'limited'||x===target+'ltd')) score+=900;
    if(names.some(x=>x.startsWith(target+'limited')||x.startsWith(target+'ltd'))) score+=700;
    if(names.some(x=>x.includes(target))) score+=400;
    if(names.some(x=>target.includes(x) && x.length>4)) score+=150;
    if(String(q.quoteType||'').toUpperCase()==='EQUITY') score+=100;
    const ex=String(q.exchange||'').toUpperCase();
    if(ex.includes('NSI')||ex.includes('NSE')) score+=50;
    if(ex.includes('BSE')) score+=20;
    score-=i*0.01;
    return {q,score};
  }).sort((a,b)=>b.score-a.score);
  if(!scored.length) throw new Error(`No Yahoo Finance listing found for "${input}".`);
  m=scored[0].q;
}

const cleanNews=news.slice(0,6).map(n=>({
  title:String(n.title||'').trim(),
  publisher:String(n.publisher||'Unknown'),
  link:n.link||null,
  publishedAt:n.providerPublishTime?new Date(n.providerPublishTime*1000).toISOString():null
})).filter(n=>n.title);

return [{json:{
  ...req,
  companyName:m.longname||m.shortname||input,
  symbol:m.symbol,
  exchange:m.exchange||'Not provided',
  region:m.region||'Not provided',
  quoteType:m.quoteType||'EQUITY',
  currency:m.currency||req.currency||'INR',
  marketNews:cleanNews,
  yahooResolved:true,
  resolutionMethod:forcedSymbol?'deterministic_alias_or_ticker':'yahoo_ranked_search'
}}];

const selected=$('Resolve Company').first().json;
const income=$('Fetch Income Statement').first().json||{};
const balance=$('Fetch Balance Sheet').first().json||{};
const cash=$('Fetch Cash Flow').first().json||{};
function result(resp){return Array.isArray(resp?.timeseries?.result)?resp.timeseries.result:(Array.isArray(resp?.result)?resp.result:[]);}
function latest(results, keys){
  for(const key of keys){
    for(const obj of results){
      const arr=obj?.[key];
      if(!Array.isArray(arr)||!arr.length) continue;
      const rows=[...arr].sort((a,b)=>new Date(b?.asOfDate||0)-new Date(a?.asOfDate||0));
      for(const row of rows){
        const v=Number(row?.reportedValue?.raw ?? row?.raw ?? row?.value);
        if(Number.isFinite(v)) return v;
      }
    }
  }
  return null;
}
const inc=result(income), bal=result(balance), cf=result(cash);
const s={
 revenue:latest(inc,['annualTotalRevenue','trailingTotalRevenue']),
 netIncome:latest(inc,['annualNetIncome','trailingNetIncome']),
 grossProfit:latest(inc,['annualGrossProfit']),
 operatingIncome:latest(inc,['annualOperatingIncome']),
 ebitda:latest(inc,['annualEBITDA']),
 interestExpense:latest(inc,['annualInterestExpense']),
 currentAssets:latest(bal,['annualTotalCurrentAssets']),
 currentLiabilities:latest(bal,['annualTotalCurrentLiabilities']),
 cash:latest(bal,['annualCashCashEquivalentsAndShortTermInvestments','annualCashFinancial']),
 inventory:latest(bal,['annualInventory']),
 totalAssets:latest(bal,['annualTotalAssets']),
 totalDebt:latest(bal,['annualTotalDebt']),
 equity:latest(bal,['annualStockholdersEquity']),
 operatingCashFlow:latest(cf,['annualOperatingCashFlow']),
 freeCashFlow:latest(cf,['annualFreeCashFlow']),
 capitalExpenditure:latest(cf,['annualCapitalExpenditure']),
 investingCashFlow:latest(cf,['annualInvestingCashFlow']),
 financingCashFlow:latest(cf,['annualFinancingCashFlow'])
};
const ratio=(a,b)=>Number.isFinite(a)&&Number.isFinite(b)&&b!==0?a/b:null;
const r={
 currentRatio:ratio(s.currentAssets,s.currentLiabilities),
 debtToEquity:ratio(s.totalDebt,s.equity),
 netMargin:ratio(s.netIncome,s.revenue),
 grossMargin:ratio(s.grossProfit,s.revenue),
 operatingMargin:ratio(s.operatingIncome,s.revenue),
 interestCoverage:(Number.isFinite(s.operatingIncome)&&Number.isFinite(s.interestExpense)&&s.interestExpense>0)?s.operatingIncome/s.interestExpense:null,
 operatingCashFlowToDebt:ratio(s.operatingCashFlow,s.totalDebt),
 fcfToDebt:ratio(s.freeCashFlow,s.totalDebt),
 cashToDebt:ratio(s.cash,s.totalDebt)
};
const missing=Object.entries(s).filter(([k,v])=>v===null).map(([k])=>k);
function stress(multRev,multEbitda,multOcf){
  const revenue=Number.isFinite(s.revenue)?s.revenue*multRev:null;
  const ebitda=Number.isFinite(s.ebitda)?s.ebitda*multEbitda:null;
  const ocf=Number.isFinite(s.operatingCashFlow)?s.operatingCashFlow*multOcf:null;
  const fcf=Number.isFinite(s.freeCashFlow)?s.freeCashFlow*multOcf:null;
  return {revenue,ebitda,operatingCashFlow:ocf,freeCashFlow:fcf,
    revenueAfterStress:revenue,ebitdaAfterStress:ebitda,ocfAfterStress:ocf,fcfAfterStress:fcf,
    interestCoverage:(Number.isFinite(ebitda)&&Number.isFinite(s.interestExpense)&&s.interestExpense>0)?ebitda/s.interestExpense:null,
    debtServiceProxy:(Number.isFinite(ocf)&&Number.isFinite(s.totalDebt)&&s.totalDebt>0)?ocf/s.totalDebt:null};
}
const stressTests={
  base:stress(1,1,1),
  downside15:stress(.85,.80,.75),
  severe30:stress(.70,.60,.50)
};
const flags=[];
if(r.currentRatio!==null&&r.currentRatio<1) flags.push('Current ratio below 1.0');
if(r.debtToEquity!==null&&r.debtToEquity>2) flags.push('Debt-to-equity above 2.0x');
if(r.netMargin!==null&&r.netMargin<0) flags.push('Negative net margin');
if(r.operatingCashFlow!==null&&r.operatingCashFlow<0) flags.push('Negative operating cash flow');
if(r.freeCashFlow!==null&&r.freeCashFlow<0) flags.push('Negative free cash flow');
if(r.interestCoverage!==null&&r.interestCoverage<1.5) flags.push('Weak interest coverage');
if(missing.length>=5) flags.push('Material financial data is missing');
const dataQuality={missingFields:missing,missingCount:missing.length,completenessScore:Math.round((Object.keys(s).length-missing.length)/Object.keys(s).length*100)};
const evidence={
 applicantId:selected.applicantId,companyName:selected.companyName,symbol:selected.symbol,exchange:selected.exchange,
 currency:selected.currency,requestedAmount:selected.requestedAmount,quoteType:selected.quoteType,
 statements:s,ratios:r,stressTests,anomalyFlags:flags,dataQuality,
 news:selected.marketNews||[]
};
return [{json:evidence}];

