const input=$input.first().json||{};
const raw=input.text ?? input.output ?? input;

function parseJson(value){
  if(value && typeof value==='object' && !Array.isArray(value)) return value;
  let s=String(value??'').replace(/```json/gi,'').replace(/```/g,'').trim();
  try{return JSON.parse(s)}catch{}
  const a=s.indexOf('{'), b=s.lastIndexOf('}');
  if(a<0||b<=a) return null;
  s=s.slice(a,b+1);
  let out='', quoted=false, esc=false;
  for(const ch of s){
    if(quoted){
      if(esc){out+=ch;esc=false;continue}
      if(ch==='\\'){out+=ch;esc=true;continue}
      if(ch==='"'){out+=ch;quoted=false;continue}
      if(ch==='\n'){out+='\\n';continue}
      if(ch==='\r'){out+='\\r';continue}
      if(ch==='\t'){out+='\\t';continue}
      out+=ch;
    }else{
      if(ch==='"') quoted=true;
      out+=ch;
    }
  }
  out=out.replace(/,\s*([}\]])/g,'$1');
  try{return JSON.parse(out)}catch{return null}
}

const base=$('Build Credit Evidence Pack').first().json;
const requested=Math.max(0,Number(base.requestedAmount)||0);
const r=base.ratios||{};
const s=base.stressTests||{};
const dq=base.dataQuality||{};
const statements=base.statements||{};

function num(v){const n=Number(v);return Number.isFinite(n)?n:null}
function clamp(n){return Math.max(0,Math.min(100,Math.round(n)))}

// Deterministic underwriting score. This is a safeguard, not an AI-generated fact.
let score=55;
const cr=num(r.currentRatio), de=num(r.debtToEquity), nm=num(r.netMargin);
const ic=num(r.interestCoverage), ocf=num(r.operatingCashFlowToDebt), fcf=num(r.fcfToDebt), cash=num(r.cashToDebt);

if(cr!==null) score += cr>=1.5?10:cr>=1.0?3:-10;
if(de!==null) score += de<=1?10:de<=2?2:-10;
if(nm!==null) score += nm>=0.10?10:nm>=0?3:-12;
if(ic!==null) score += ic>=3?10:ic>=1.5?3:-12;
if(ocf!==null) score += ocf>=0.20?8:ocf>=0?2:-10;
if(fcf!==null) score += fcf>=0.10?6:fcf>=0?1:-8;
if(cash!==null) score += cash>=0.50?6:cash>=0.20?2:-4;
if((dq.missingFields||[]).length) score -= Math.min(12,(dq.missingFields||[]).length*4);

const severeOcf=num(s.severe30?.ocfAfterStress ?? s.severe30?.operatingCashFlow);
if(severeOcf!==null && severeOcf<0) score-=8;

score=clamp(score);
const deterministicDecision=score>=75?'Approve':score>=50?'Review':'Reject';
const deterministicRisk=score>=75?'Low':score>=50?'Medium':'High';

let result=parseJson(raw);
const agentScores=[
  parseJson($('Financial Health Agent').first().json.text),
  parseJson($('Cash Flow & Repayment Agent').first().json.text),
  parseJson($('Industry & Market Agent').first().json.text),
  parseJson($('Anomaly & Stress Agent').first().json.text)
].filter(Boolean);

const allAgentZero=agentScores.length===0 || agentScores.every(a=>Number(a.score||0)===0);

// If the committee produced an empty/zero assessment while deterministic evidence is available,
// use the deterministic safeguard instead of returning an unusable 0-confidence result.
if(!result || typeof result!=='object' || Array.isArray(result) ||
   allAgentZero ||
   Number(result.overall_confidence||0)===0){
  result={
    companyName:base.companyName,
    symbol:base.symbol,
    decision:deterministicDecision,
    proposed_exposure:deterministicDecision==='Approve'?requested:0,
    currency:base.currency||'INR',
    overall_confidence:Math.max(50,Math.min(90,score)),
    credit_metrics:{
      financial_health:score,
      cash_flow:score,
      repayment_capacity:score,
      deterministic_score:score
    },
    key_risks:[],
    mitigating_conditions:[],
    supporting_evidence:[
      `Deterministic underwriting score: ${score}/100.`,
      `Debt-to-equity: ${de===null?'Not provided':de.toFixed(2)}x.`,
      `Interest coverage: ${ic===null?'Not provided':ic.toFixed(2)}x.`
    ],
    committee_rationale:'Committee safeguard applied because the AI assessment was incomplete; decision is grounded in supplied financial ratios and stress evidence.',
    committee_fallback:true
  };
}

result.companyName=result.companyName||base.companyName;
result.symbol=result.symbol||base.symbol;
result.currency=result.currency||base.currency||'INR';

const proposed=num(result.proposed_exposure);
result.proposed_exposure=Math.max(0,Math.min(proposed===null?0:proposed,requested));
result.decision=['Approve','Review','Reject'].includes(result.decision)?result.decision:'Review';

const conf=num(result.overall_confidence);
result.overall_confidence=clamp(conf===null?0:conf);

result.credit_metrics=result.credit_metrics&&typeof result.credit_metrics==='object'?result.credit_metrics:{};
for(const k of ['financial_health','cash_flow','repayment_capacity','deterministic_score']){
  const n=num(result.credit_metrics[k]);
  result.credit_metrics[k]=clamp(n===null?0:n);
}
for(const k of ['key_risks','mitigating_conditions','supporting_evidence']){
  if(!Array.isArray(result[k])) result[k]=[];
  result[k]=result[k].map(v=>String(v)).filter(Boolean).slice(0,3);
}
result.committee_rationale=String(result.committee_rationale||'').slice(0,500);

// Per-agent safeguard: if a specialist's own score is missing/zero (which our testing shows
// only ever happens when the model failed to analyze, never as a genuine finding), fall back
// to the deterministic score computed above rather than surfacing a broken "0/100" card.
function agentOrFallback(parsed, label){
  const s = parsed ? num(parsed.score) : null;
  const isValid = s !== null && s > 0;
  if (isValid) return parsed;
  return {
    score: score,
    risk: deterministicRisk,
    findings: [`Automated ${label} assessment was inconclusive this run; score reflects verified financial ratios instead.`],
    fallbackApplied: true
  };
}

const financialHealthParsed=agentOrFallback(parseJson($('Financial Health Agent').first().json.text), 'financial health');
const cashFlowParsed=agentOrFallback(parseJson($('Cash Flow & Repayment Agent').first().json.text), 'cash flow');
const industryMarketParsed=agentOrFallback(parseJson($('Industry & Market Agent').first().json.text), 'industry & market');
const anomalyStressParsed=agentOrFallback(parseJson($('Anomaly & Stress Agent').first().json.text), 'anomaly & stress');

return [{json:{
  ...result,
  requested_exposure:requested,
  financials:statements,
  ratios:base.ratios||{},
  stressTests:base.stressTests||{},
  anomalyFlags:base.anomalyFlags||[],
  dataQuality:base.dataQuality||{},
  marketNews:base.marketNews||base.news||[],
  agentAssessments:{
    financialHealth:financialHealthParsed,
    cashFlowRepayment:cashFlowParsed,
    industryMarket:industryMarketParsed,
    anomalyStress:anomalyStressParsed
  },
  generatedAt:new Date().toISOString(),
  system:'CrediLens AI Multi-Agent Credit Intelligence & Underwriting System'
}}];
